vec2 p2xy(vec2 p) {
    vec2 r = iResolution.xy;
    vec2 a = r.x > r.y ? r.xx : r.yy;
    return (p/r*2. - 1.) * r/a;
}

vec3 color(float t) {
    return vec3(t, t*t*0.4, t*t*t*0.15);
}

void mainImage(out vec4 o, vec2 p) {
    vec2 r = p2xy(p);
    float rad = length(r);
    float phi = atan(r.x, r.y);

    vec4 b = texture(iChannel1, vec2(phi/PI*0.5 + 0.5, log(1.0 + rad)*0.05));
    o.rgb = color(pow(2.0*b.z, 2.5));
    o.a = 1.;
}

vec2 mainSound(int samp, float time) {
    return guitarSound(samp, iSampleRate);
}

